mapper.select:
SELECT * FROM ( SELECT B.BOARD_NO, B.TITLE AS BOARD_TITLE, B.CONTENT AS BOARD_CONTENT, B.VIEW_COUNT AS READ_COUNT, TO_CHAR(B.CREATED_AT, 'YYYY-MM-DD') AS CREATED_AT, M.NICKNAME AS MEMBER_NICKNAME, M.PROFILE_IMAGE AS MEMBER_PROFILE, NVL(cc.COMMENT_COUNT, 0) AS COMMENT_COUNT, NVL(lc.LIKE_COUNT, 0) AS LIKE_COUNT, bi.IMAGE_URLS, ROW_NUMBER() OVER (ORDER BY B.BOARD_NO DESC) AS RN FROM BOARD B JOIN MEMBER M ON B.MEMBER_NO = M.MEMBER_NO LEFT JOIN ( SELECT BOARD_NO, COUNT(*) AS COMMENT_COUNT FROM COMMENT_TBL WHERE STATUS = 'A' GROUP BY BOARD_NO ) cc ON cc.BOARD_NO = B.BOARD_NO LEFT JOIN ( SELECT BOARD_NO, COUNT(*) AS LIKE_COUNT FROM BOARD_LIKE GROUP BY BOARD_NO ) lc ON lc.BOARD_NO = B.BOARD_NO LEFT JOIN ( SELECT BOARD_NO, MIN(IMAGE_URL) AS IMAGE_URLS FROM BOARD_IMAGE WHERE IMAGE_ORDER = 0 GROUP BY BOARD_NO ) bi ON bi.BOARD_NO = B.BOARD_NO WHERE B.BOARD_CODE = 'FREE' AND B.STATUS = 'A'
AND (B.TITLE LIKE '%' || #{search} || '%' OR B.CONTENT LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE BOARD
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE BOARD_NO = #{boardNo}

UPDATE BOARD
SET TITLE = #{boardTitle},
    CONTENT = #{boardContent},
    UPDATED_AT = SYSDATE
WHERE BOARD_NO = #{boardNo}
  AND MEMBER_NO = #{memberNo}

UPDATE BOARD
SET STATUS = 'D', UPDATED_AT = SYSDATE
WHERE BOARD_NO = #{boardNo}
  AND MEMBER_NO = #{memberNo}

UPDATE BOARD
SET STATUS = 'D', UPDATED_AT = SYSDATE
WHERE BOARD_NO = #{boardNo}

UPDATE COMMENT_TBL
SET STATUS = 'D'
WHERE COMMENT_NO = #{commentNo}
  AND MEMBER_NO = #{memberNo}

